import { Group, Mesh, PlaneGeometry, Vector2, Color } from 'three';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
	uv,
	texture,
	mul,
	add,
	sub,
	mix,
	vec3,
	vec4,
	// basic math helpers
	smoothstep,
	pow,
	dot,
	normalize,
	viewDirection,
	normalWorld,
} from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {Array<Object>} [textContent]
 * @property {Object} [visualSpec]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture(url:string):Promise<any> }} textureLoader
 * @property {{ loadGLB(url:string):Promise<any> }} glbLoader
 * @property {{ loadVideo?(url:string):Promise<any> }} videoLoader
 * @property {{ createText(content:string, opts?:any):any }} fontAtlas
 * @property {{ [key:string]: (target:any, params:any)=>{timeline:any, cleanup:()=>void} }} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
	const { Group: CGroup, Mesh: CMesh, PlaneGeometry, Vector2 } = ctx.THREE;

	// Root group
	const root = new CGroup();

	// -----------------------------------------------------------------
	// Load required textures
	const imagePromise = ctx.textureLoader.loadTexture(config.imageUrl);
	const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

	// -----------------------------------------------------------------
	// Build hero plate once textures are ready
	Promise.all([imagePromise, depthPromise]).then(([colorTex, depthTex]) => {
		// Geometry (4.0 x 2.5 units, 64 x 64 segments)
		const geometry = new PlaneGeometry(4.0, 2.5, 64, 64);

		// Material with node graph
		const material = new MeshStandardNodeMaterial();
		material.transparent = true;
		material.side = ctx.THREE.DoubleSide;

		// Base color map node
		const colorNode = texture(colorTex);
		material.mapNode = colorNode;

		// Displacement node (depth map * amplitude)
		const dispAmplitude = uniform(0.18);
		const dispNode = mul(texture(depthTex), dispAmplitude);
		material.displacementNode = dispNode;

		// Rim lighting (key light rim 0.02 units thick)
		const viewDir = viewDirection;
		const nWorld = normalWorld;
		const rimFactor = smoothstep(0.0, 0.02, sub(1.0, dot(normalize(nWorld), viewDir)));
		const rimColor = vec3(1.0); // white rim
		material.emissiveNode = mul(rimFactor, rimColor);
		material.emissiveIntensity = 0.8;

		// Simple filmic grade (contrast + saturation tweak)
		const contrastNode = mix(colorNode, sub(colorNode, 0.5), uniform(0.12)); // crude contrast boost
		const satNode = mul(contrastNode, uniform(0.92)); // -8% desaturation, preserves red approx.
		material.colorNode = satNode;

		// Mesh
		const mesh = new CMesh(geometry, material);
		mesh.position.set(0, 0, 0);
		root.add(mesh);

		// -----------------------------------------------------------------
		// Bottom scrim gradient for caption block
		const scrimGeometry = new PlaneGeometry(4.0, 0.6, 1, 1);
		const scrimMaterial = new MeshStandardNodeMaterial();
		scrimMaterial.transparent = true;
		const bottomColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
		const topColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
		const gradNode = mix(
			bottomColor,
			topColor,
			smoothstep(0.45, 1.0, uv().y)
		);
		scrimMaterial.colorNode = gradNode;
		const scrimMesh = new CMesh(scrimGeometry, scrimMaterial);
		scrimMesh.position.set(0, -1.2, 0.01); // bottom of hero plate
		root.add(scrimMesh);

		// -----------------------------------------------------------------
		// Accent hairline bar
		const barGeometry = new PlaneGeometry(0.75, 0.02, 1, 1);
		const barMaterial = new MeshStandardNodeMaterial();
		barMaterial.emissiveNode = vec3(1.0, 0.165, 0.22); // #ff2a38 normalized
		barMaterial.emissiveIntensity = 1.8;
		barMaterial.transparent = true;
		const barMesh = new CMesh(barGeometry, barMaterial);
		barMesh.position.set(0, -0.8, 0.02);
		root.add(barMesh);

		// -----------------------------------------------------------------
		// Text layout
		const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
		const padding = 0.5; // base unit *2
		const lineHeight = 0.25; // baseline rhythm
		// Compute starting Y (bottom of scrim)
		let cursorY = -1.2 + padding; // bottom of scrim + padding

		const textGroup = new CGroup();
		root.add(textGroup);

		for (const item of textItems) {
			const opts = {
				fontSize: item.typography?.fontSize ?? 13,
				color: config.visualSpec?.colors?.ink ?? '#16161d',
				align: 'left',
				letterSpacingPx: (item.typography?.letterSpacing ?? 0) * (item.typography?.fontSize ?? 13),
			};
			const txtObj = ctx.fontAtlas.createText(item.text ?? '', opts);
			txtObj.position.set(-2.0 + padding, cursorY, 0.03); // left edge + padding
			textGroup.add(txtObj);
			// Advance cursor based on role hierarchy
			if (item.role === 'kicker' || item.role === 'headline') {
				cursorY += lineHeight;
			} else if (item.role === 'body') {
				cursorY += lineHeight;
			} else if (item.role === 'caption') {
				cursorY += lineHeight;
			}
		}

		// -----------------------------------------------------------------
		// GSAP animations
		const mountTL = gsap.timeline();
		mountTL.from(
			material,
			{
				opacity: 0,
				duration: 0.5,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			},
			0
		);

		const captionTL = gsap.timeline({ delay: 0.12 });
		captionTL.from(
			textGroup.position,
			{
				y: '+=' + 0.4,
				duration: 0.7,
				ease: 'cubic-bezier(0.215,0.61,0.355,1)',
			},
			0
		);

		// Store timelines for cleanup
		root.userData._timelines = [mountTL, captionTL];
	});

	// -----------------------------------------------------------------
	// Apply cinematic primitives
	const primitiveHandles = [];
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const handler = ctx.primitives[prim.name];
			if (handler) {
				const result = handler(root, prim.params || {});
				primitiveHandles.push(result);
			}
		}
	}
	// -----------------------------------------------------------------
	// User data for handlers and cleanup
	root.userData.handlers = {};
	root.userData.cleanup = () => {
		// Dispose meshes, geometries, materials, textures
		root.traverse((obj) => {
			if (obj.isMesh) {
				if (obj.geometry) obj.geometry.dispose();
				if (obj.material) {
					if (Array.isArray(obj.material)) {
						obj.material.forEach((m) => m.dispose());
					} else {
						obj.material.dispose();
					}
				}
			}
		});
		// Kill GSAP timelines
		if (root.userData._timelines) {
			root.userData._timelines.forEach((tl) => tl.kill());
		}
		// Cleanup primitives
		primitiveHandles.forEach((h) => {
			if (h && typeof h.cleanup === 'function') h.cleanup();
		});
	};

	return root;
}
